import {puppets,settings,actions,props,invitationById,audienceQuestions} from './loft-content.mjs';
const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x),int=(x,a=0,b=1000000000)=>Number.isSafeInteger(x)&&x>=a&&x<=b;
const keys=(x,list)=>object(x)&&Object.keys(x).sort().join(',')===list.split(',').sort().join(',');
const catalogs={actor:puppets,place:settings,action:actions,prop:props};
const validOldScene=f=>keys(f,'actor,place,action,prop')&&Object.entries(catalogs).every(([k,items])=>items.some(x=>x.id===f[k]));
export const MAX_SCENES=12,MAX_DIALOGUE=400;
export const validScene=f=>validOldScene(f)||(keys(f,'actor,place,action,prop,dialogue')&&validOldScene(Object.fromEntries(Object.entries(f).filter(([k])=>k!=='dialogue')))&&typeof f.dialogue==='string'&&f.dialogue.length<=MAX_DIALOGUE);
function showValid(s,version){const last=s?.frames?.length-1;return keys(s,'id,invitation,frames,selected,mode,stage,question,spotlight,changes,shared,heard'+(version===2?',editor,choice':''))&&int(s.id,1)&&!!invitationById(s.invitation)&&Array.isArray(s.frames)&&(version===1?s.frames.length===3:int(s.frames.length,1,MAX_SCENES))&&s.frames.every(f=>version===1?validOldScene(f):validScene(f)&&Object.hasOwn(f,'dialogue'))&&int(s.selected,0,last)&&['edit','perform','audience'].includes(s.mode)&&int(s.stage,0,last)&&int(s.question,0,audienceQuestions.length-1)&&(s.spotlight===null||int(s.spotlight,0,last))&&int(s.changes)&&typeof s.shared==='boolean'&&typeof s.heard==='boolean'&&(version===1||['pictures','words','order'].includes(s.editor)&&int(s.choice,0,3));}
export const validShow=s=>showValid(s,2);
export function validLoft(l){return keys(l,'version,nextId,draft,shelf')&&[1,2].includes(l.version)&&int(l.nextId,1)&&Array.isArray(l.shelf)&&l.shelf.length<=12&&l.shelf.every(s=>showValid(s,l.version)&&s.id<l.nextId)&&new Set(l.shelf.map(s=>s.id)).size===l.shelf.length&&(l.draft===null||showValid(l.draft,l.version)&&l.draft.id<l.nextId);}
const fresh=()=>({version:2,nextId:1,draft:null,shelf:[]});
const adaptShow=s=>s?{...structuredClone(s),frames:s.frames.map(f=>({...f,dialogue:''})),editor:'pictures',choice:0}:null;
// Adapt only known v1 saves; reads never change the source or future payloads.
export const loftState=state=>{if(!Object.hasOwn(state,'loft'))return fresh();const l=state.loft;if(!validLoft(l))return null;return l.version===2?l:{version:2,nextId:l.nextId,draft:adaptShow(l.draft),shelf:l.shelf.map(adaptShow)};};
function change(state,fn){const l=loftState(state);if(!l)return false;const next=structuredClone(l);if(!fn(next)||!validLoft(next))return false;state.loft=next;return true;}
function shelve(l){if(!l.draft)return;l.shelf=l.shelf.filter(s=>s.id!==l.draft.id);l.shelf.push(structuredClone(l.draft));l.shelf=l.shelf.slice(-12);}
export function startShow(state,id){return change(state,l=>{const idea=invitationById(id);if(!idea||l.nextId>=1000000000)return false;shelve(l);l.draft={id:l.nextId++,invitation:id,frames:idea.frames.map(f=>({...f,dialogue:''})),editor:'pictures',choice:0,selected:0,mode:'edit',stage:0,question:(l.nextId-2)%audienceQuestions.length,spotlight:null,changes:0,shared:false,heard:false};return true;});}
export function chooseScene(state,index){return change(state,l=>{const d=l.draft;if(!d||!int(index,0,d.frames.length-1)||d.mode!=='edit')return false;d.selected=index;return true;});}
export function setScenePart(state,part,value){return change(state,l=>{const d=l.draft;if(!d||d.mode!=='edit'||!Object.hasOwn(catalogs,part)||!catalogs[part].some(x=>x.id===value)||d.frames[d.selected][part]===value||d.changes>=1000000000)return false;d.frames[d.selected][part]=value;d.changes++;d.shared=false;return true;});}
export function moveScene(state,delta){return change(state,l=>{const d=l.draft;if(!d||d.mode!=='edit'||![-1,1].includes(delta)||!int(d.selected+delta,0,d.frames.length-1)||d.changes>=1000000000)return false;const target=d.selected+delta;[d.frames[d.selected],d.frames[target]]=[d.frames[target],d.frames[d.selected]];d.selected=target;d.changes++;d.shared=false;return true;});}
export function performShow(state){return change(state,l=>{if(!l.draft)return false;l.draft.mode='perform';l.draft.stage=0;l.draft.spotlight=null;return true;});}
export function stepShow(state,delta){return change(state,l=>{const d=l.draft;if(!d||d.mode!=='perform'||![-1,1].includes(delta)||!int(d.stage+delta,0,d.frames.length-1))return false;d.stage+=delta;return true;});}
export function meetAudience(state){return change(state,l=>{const d=l.draft;if(!d||d.mode!=='perform'||d.stage!==d.frames.length-1)return false;d.mode='audience';d.shared=true;d.spotlight=null;shelve(l);return true;});}
export function spotlightScene(state,index){return change(state,l=>{const d=l.draft;if(!d||d.mode!=='audience'||!int(index,0,d.frames.length-1))return false;d.spotlight=index;d.stage=index;return true;});}
export function nextAudienceQuestion(state){return change(state,l=>{const d=l.draft;if(!d||d.mode!=='audience')return false;d.question=(d.question+1)%audienceQuestions.length;return true;});}
export function chooseAudienceQuestion(state,index){return change(state,l=>{const d=l.draft;if(!d||d.mode!=='audience'||!int(index,0,audienceQuestions.length-1))return false;d.question=index;return true;});}
export function reviseShow(state,index){return change(state,l=>{const d=l.draft;if(!d||!int(index??d.stage,0,d.frames.length-1))return false;d.selected=index??d.stage;d.mode='edit';return true;});}
export function reopenShow(state,id){return change(state,l=>{const saved=l.shelf.find(s=>s.id===id);if(!saved||l.draft?.id===id)return false;const next=structuredClone(saved);shelve(l);l.draft=next;l.draft.mode='edit';l.draft.selected=0;return true;});}
export function noteLoftAudio(state){return change(state,l=>{if(!l.draft)return false;l.draft.heard=true;return true;});}

export function setLoftEditor(state,page,choice){return change(state,l=>{const d=l.draft;if(!d||d.mode!=='edit'||!['pictures','words','order'].includes(page)||choice!==undefined&&!int(choice,0,3))return false;d.editor=page;if(choice!==undefined)d.choice=choice;return true;});}
export function setSceneDialogue(state,text){return change(state,l=>{const d=l.draft;if(!d||d.mode!=='edit'||typeof text!=='string'||text.length>MAX_DIALOGUE||text===d.frames[d.selected].dialogue||d.changes>=1000000000)return false;d.frames[d.selected].dialogue=text;d.changes++;d.shared=false;return true;});}
export function addScene(state){return change(state,l=>{const d=l.draft;if(!d||d.mode!=='edit'||d.frames.length>=MAX_SCENES||d.changes>=1000000000)return false;d.frames.splice(d.selected+1,0,structuredClone(d.frames[d.selected]));d.selected++;d.changes++;d.shared=false;return true;});}
export function removeScene(state){return change(state,l=>{const d=l.draft;if(!d||d.mode!=='edit'||d.frames.length<=1||d.changes>=1000000000)return false;const i=d.selected;d.frames.splice(i,1);const repair=n=>n===null?null:Math.min(n>i?n-1:n,d.frames.length-1);d.selected=repair(i);d.stage=repair(d.stage);d.spotlight=repair(d.spotlight);d.changes++;d.shared=false;return true;});}
